Lemma rs_seg2 : asan_memset_stmt ->
  forall (pcv rax sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (s4v s3v s2v s1v s0v rav : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (D ptr len lo : Z),
  rw_cells asegs m (bv_unsigned sp + -64) (rs_frame s4v s3v s2v s1v s0v rav) ->
  rw_cells asegs m D [C8 (wz ptr); C8 (wz len)] ->
  stk asegs m lo (bv_unsigned sp + -64) -> lo + 64 + AINTRIN_STACK <= bv_unsigned sp -> aceil <= lo ->
  aapp D 16 -> accessible m D 16 -> shvis m D (D + 16) ->
  mem_inv asegs m -> ACONST m ->
  (pcv = wz RS_RA_DEL \/ pcv = ret_pc (wz RS_RA_DEL)) ->
  evt asegs (fun ms' => exists t0v t1v t2v a0v a1v a2v a3v a4v a5v a6v a7v t3v t4v t5v t6v m',
      ms' = MS (mkR rav sp gp tp t0v t1v t2v s0v s1v a0v a1v a2v a3v a4v a5v a6v a7v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 t3v t4v t5v t6v)
