    (MS (mkR rax (wz (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz D) (wz (D + 8)) a0 a1 a2 a3 a4 a5 a6 a7
             s2x (wz (Z.shiftr (D + 8) 3 + 2147450880)) (wz 2147450880) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
