Definition ASvOwn (LB : list block) (m : mem) (ptr len : Z) : Prop :=
  (len = 0 /\ ptr = 0)
  \/ (1 <= len /\ exists p bs, In (p, ptr, len) LB /\ rw_cells asegs m ptr [CB (Z.to_nat len) bs] /\ addressable m ptr len).
Definition svowned (ptr len : Z) (b : block) : Prop := 1 <= len /\ blk_addr b = ptr /\ blk_size b = len.

